Looking at the code, I can identify several issues and opportunities for refactoring:

1. **Magic numbers**: `1` and `0` are used repeatedly for labels - should be replaced with symbolic constants
2. **Code duplication**: The `update` method is called multiple times across different methods, and the logic for computing each metric has repeated patterns
3. **Fields should be encapsulated**: The public fields `true_positives`, `false_positives`, etc. should be made private and accessed through methods
4. **Duplicate conditional fragments**: The zero-check and division pattern is repeated
5. **Separate Query from Modifier**: `update` modifies state, while `precision`, `recall` etc. are queries that also modify state - this violates the separation principle
6. **Extract Method**: Some computations could be extracted into helper methods

Let me apply these refactorings:

```python
class MetricsCalculator:
    POSITIVE_LABEL = 1
    NEGATIVE_LABEL = 0

    def __init__(self):
        self._true_positives = 0
        self._false_positives = 0
        self._false_negatives = 0
        self._true_negatives = 0

    def _reset(self):
        self._true_positives = 0
        self._false_positives = 0
        self._false_negatives = 0
        self._true_negatives = 0

    def _update_from_labels(self, predicted_labels, true_labels):
        self._reset()
        for predicted, true in zip(predicted_labels, true_labels):
            if predicted == self.POSITIVE_LABEL and true == self.POSITIVE_LABEL:
                self._true_positives += 1
            elif predicted == self.POSITIVE_LABEL and true == self.NEGATIVE_LABEL:
                self._false_positives += 1
            elif predicted == self.NEGATIVE_LABEL and true == self.POSITIVE_LABEL:
                self._false_negatives += 1
            elif predicted == self.NEGATIVE_LABEL and true == self.NEGATIVE_LABEL:
                self._true_negatives += 1

    @property
    def true_positives(self):
        return self._true_positives

    @property
    def false_positives(self):
        return self._false_positives

    @property
    def false_negatives(self):
        return self._false_negatives

    @property
    def true_negatives(self):
        return self._true_negatives

    def _safe_divide(self, numerator, denominator):
        if denominator == 0:
            return 0.0
        return numerator / denominator

    def precision(self, predicted_labels, true_labels):
        self._update_from_labels(predicted_labels, true_labels)
        return self._safe_divide(self._true_positives, self._true_positives + self._false_positives)

    def recall(self, predicted_labels, true_labels):
        self._update_from_labels(predicted_labels, true_labels)
        return self._safe_divide(self._true_positives, self._true_positives + self._false_negatives)

    def f1_score(self, predicted_labels, true_labels):
        self._update_from_labels(predicted_labels, true_labels)
        p = self.precision(predicted_labels, true_labels)
        r = self.recall(predicted_labels, true_labels)
        return self._safe_divide(2 * p * r, p + r)

    def accuracy(self, predicted_labels, true_labels):
        self._update_from_labels(predicted_labels, true_labels)
        total = (self._true_positives + self._true_negatives + 
                 self._false_positives + self._false_negatives)
        return self._safe_divide(self._true_positives + self._true_negatives, total)
```

